import{_ as e,o as t,c as s,a5 as i}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"为什么link用href获取资源 script和img用src","description":"src用于替换当前元素，href用于在当前文档和引用资源之间确立联系。 src src是source的缩写，指向外部资源的位置，指向的内容将会嵌入到文档中当前标签所在位置；在请求src资源时会将其指向的资源下载并应用到文档内，例如js脚本，img图片和frame等元素 \\\\<scr。","frontmatter":{"title":"为什么link用href获取资源 script和img用src","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","语言与运行时"],"description":"src用于替换当前元素，href用于在当前文档和引用资源之间确立联系。 src src是source的缩写，指向外部资源的位置，指向的内容将会嵌入到文档中当前标签所在位置；在请求src资源时会将其指向的资源下载并应用到文档内，例如js脚本，img图片和frame等元素 \\\\<scr。","sidebarWeight":14,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/概述/为什么link用href获取资源 script和img用src.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/01-语言与运行时/为什么link用href获取资源 script和img用src.md","filePath":"posts/JavaScript系统教程/01-语言与运行时/为什么link用href获取资源 script和img用src.md"}'),c={name:"posts/JavaScript系统教程/01-语言与运行时/为什么link用href获取资源 script和img用src.md"};function a(l,r,o,n,p,m){return t(),s("div",null,[...r[0]||(r[0]=[i('<div><h1 id="为什么link用href获取资源-script和img用src" tabindex="-1">为什么link用href获取资源 script和img用src <a class="header-anchor" href="#为什么link用href获取资源-script和img用src" aria-label="Permalink to &quot;为什么link用href获取资源 script和img用src&quot;">​</a></h1><blockquote><p>本节目标：理解“为什么link用href获取资源 script和img用src”的核心思路，并能把它用于实际开发或面试表达。 ==src用于替换当前元素，href用于在当前文档和引用资源之间确立联系。== ==src==</p></blockquote><ul><li>==src是source的缩写，指向外部资源的位置，指向的内容将会嵌入到文档中当前标签所在位置；在请求src资源时会将其指向的资源下载并应用到文档内，例如js脚本，img图片和frame等元素========&lt;script src =&quot;js.js&quot;&gt;&lt;/script&gt;==</li></ul><p>==当浏览器解析到该元素时，会暂停其他资源的下载和处理，直到将该资源加载、编译、执行完毕，图片和框架 等元素也如此，类似于将所指向资源嵌入当前标签内。这也是为什么将js脚本放在底部而不是头部== ==href==</p><ul><li>==href是Hypertext Reference的缩写，指向网络资源所在位置，建立和当前元素（锚点）或当前文档（链接）之间的链接==</li><li>==在文档中添加link标签，浏览器会识别该文档为css文件，就会并行下载资源并且不会停止对当前文档的处理。这也是为什么建议使用link方式来加载css，而不是使用@import方式========&lt;link href=&quot;common.css&quot; rel=&quot;stylesheet&quot;/&gt;== &gt; 来自 &lt;<a href="http://www.manongjc.com/detail/28-mbbefietrrevuqt.html" target="_blank" rel="noreferrer">http://www.manongjc.com/detail/28-mbbefietrrevuqt.html</a>&gt;</li></ul></div>',1)])])}const h=e(c,[["render",a]]);export{_ as __pageData,h as default};
